  "source_code": "import math
def _clamp(v, lo, hi):
    if not math.isfinite(v):
        return (lo + hi) * 0.5
    if v < lo:
        return lo
    if v > hi:
        return hi
    return v
def _alpha(dt, tau):
    if tau <= 0.0:
        return 1.0
    a = dt / (tau + dt)
    if a < 0.0:
        return 0.0
    if a > 1.0:
        return 1.0
    return a
def control(obs, state):
    ff = 0.54
    kp = 0.90
    ki = 0.08
    kd = 0.45
    tau_f = 0.7
    tau_d = 1.2
    ramp = 0.03
