        u = ff
        integ = integ_prev
    if yf > 0.80:
        if u > 0.25:
            u = 0.25
    elif yf > 0.75:
        if u > 0.40:
            u = 0.40
    if y_raw > 0.83 or yf > 0.84:
        u = 0.0
    u = _clamp(u, 0.0, 1.0)
    if not first:
        max_du = 3.0 * dt + 0.02
        du = u - prev_u
        if du > max_du:
            u = prev_u + max_du
        elif du < -max_du:
            u = prev_u - max_du
        u = _clamp(u, 0.0, 1.0)
        if y_raw > 0.83 or yf > 0.84:
            u = 0.0
    new_state = {"yf": float(yf), "integ": float(integ), "dfilt": float(dfilt), "rsp": float(rsp), "prev_u": float(u)}
    return (float(u), new_state)
